html:
{%- set is_rtl = is_rtl() -%}
{%- set text_dir = "rtl" if is_rtl else "ltr" -%}
{%- set align_start = "right" if is_rtl else "left" -%}
{%- set align_end = "left" if is_rtl else "right" -%}
{%- set company_doc = frappe.get_cached_doc("Company", doc.company) -%}
{%- set company_address_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") -%}
{%- set company_address = frappe.get_cached_doc("Address", company_address_name) if company_address_name else None -%}
{%- set customer_tax_id = frappe.db.get_value("Customer", doc.party_name, "tax_id") -%}
<div class="page-break" dir="{{ text_dir }}">
	<table style="width: 100%; border-bottom: 2px solid #1c1b19; padding-bottom: 10px; margin-bottom: 14px;">
		<tr>
			<td style="width: 60%; vertical-align: top; text-align: {{ align_start }};">
				<div style="font-size: 14px; font-weight: bold;">{{ company_doc.company_name }}</div>
				<div style="font-size: 9px; color: #666; margin-bottom: 6px;">{{ _("Computerized Document") }}</div>
				<div style="font-size: 9.5px; color: #444;">
					{% if company_address %}
					<div>{{ company_address.address_line1 }}{% if company_address.city %}, {{ company_address.city }}{% endif %}{% if company_address.pincode %} {{ company_address.pincode }}{% endif %}</div>
					{% endif %}
					{% if company_doc.tax_id %}<div>{{ _("Company ID") }}: {{ company_doc.tax_id }}</div>{% endif %}
					{% if company_doc.phone_no %}<div>{{ _("Phone") }}: {{ company_doc.phone_no }}</div>{% endif %}
					{% if company_doc.fax %}<div>{{ _("Fax") }}: {{ company_doc.fax }}</div>{% endif %}
					{% if company_doc.email %}<div>{{ _("Email") }}: {{ company_doc.email }}</div>{% endif %}
					{% if company_doc.website %}<div>{{ _("Website") }}: {{ company_doc.website }}</div>{% endif %}
				</div>
			</td>
			<td style="width: 40%; vertical-align: top; text-align: {{ align_end }};">
				<div style="font-size: 13px; font-weight: bold; margin-bottom: 4px;">{{ _("Quotation") }} {{ doc.name }}</div>
				<div style="font-size: 10.5px;">{{ _("Date") }}: {{ frappe.utils.format_date(doc.transaction_date) }}</div>
				{% if doc.valid_till %}<div style="font-size: 10.5px;">{{ _("Valid Till") }}: {{ frappe.utils.format_date(doc.valid_till) }}</div>{% endif %}
			</td>
		</tr>
	</table>

	<div style="margin-bottom: 14px; text-align: {{ align_start }};">
		<div style="font-weight: bold;">{{ _("To") }}: {{ doc.customer_name }}</div>
		{% if customer_tax_id %}<div style="color: #444; font-size: 10.5px;">{{ _("Tax ID") }}: {{ customer_tax_id }}</div>{% endif %}
	</div>

	<table class="table table-bordered items-table" style="width: 100%;">
		<thead>
			<tr>
				<th style="text-align: {{ align_start }};">{{ _("Description") }}</th>
				<th style="text-align: center;">{{ _("Unit Price") }}</th>
				<th style="text-align: center;">{{ _("Qty") }}</th>
				<th style="text-align: {{ align_end }};">{{ _("Total") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td style="text-align: {{ align_start }};">
					{{ item.item_name }}
					{% if item.description and item.description != item.item_name %}
					<div class="item-description">{{ item.description }}</div>
					{% endif %}
					{% if item.term_price_breakdown %}
					<div class="term-breakdown">{{ item.term_price_breakdown }}</div>
					{% endif %}
				</td>
				<td style="text-align: center;">{{ item.get_formatted("rate") }}</td>
				<td style="text-align: center;">{{ item.get_formatted("qty") }}</td>
				<td style="text-align: {{ align_end }}; font-weight: bold;">{{ item.get_formatted("amount") }}</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>

	<table style="width: 100%; margin-top: 10px;">
		<tr>
			<td style="width: 55%;"></td>
			<td style="width: 45%;">
				<table class="totals-table" style="width: 100%;">
					<tr>
						<td style="text-align: {{ align_start }};">{{ _("Total before VAT") }}</td>
						<td style="text-align: {{ align_end }};">{{ doc.get_formatted("net_total") }}</td>
					</tr>
					{% for tax in doc.taxes %}
					{% if tax.base_tax_amount %}
					<tr>
						<td style="text-align: {{ align_start }};">{{ _("VAT") }} {{ tax.rate }}%</td>
						<td style="text-align: {{ align_end }};">{{ tax.get_formatted("base_tax_amount") }}</td>
					</tr>
					{% endif %}
					{% endfor %}
					<tr class="grand-total-row">
						<td style="text-align: {{ align_start }};">{{ _("Total incl. VAT") }}</td>
						<td style="text-align: {{ align_end }};">{{ doc.get_formatted("grand_total") }}</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>

	{% if doc.terms %}
	<div style="margin-top: 20px; text-align: {{ align_start }};">
		<strong>{{ _("Terms and Conditions") }}</strong>
		<div>{{ doc.terms }}</div>
	</div>
	{% endif %}

	<div class="signature-row" style="margin-top: 40px; text-align: {{ align_start }};">
		{{ _("Signature") }}: <span class="sig-line"></span>
	</div>
</div>

